n}\\n#arcadeHeroSwiper .hero-slide-content,\\n.hero-slide-content {\\n  width: 50% !important;\\n  height: 100% !important;\\n  flex: 0 0 50% !important;\\n  padding: 30px 40px 36px 30px !important;\\n  display: flex !important;\\n  flex-direction: column !important;\\n  justify-content: center !important;\\n  box-sizing: border-box !important;\\n  font-family: -apple-system, BlinkMacSystemFont, \\\"Segoe UI\\\", Roboto, sans-serif !important;\\n  z-index: 3 !important;\\n}\\n.hero-badge {\\n  display: inline-flex !important;\\n  align-items: center !important;\\n  align-self: flex-start !important;\\n  font-size: 11px !important;\\n  font-weight: 800 !important;\\n  letter-spacing: 1px !important;\\n  padding: 4px 12px !important;\\n  border-radius: 20px !important;\\n  border: 1px solid !important;\\n  margin-bottom: 12px !important;\\n  text-transform: uppercase !important;\\n}\\n.hero-title {\\n  color: #ffffff !important;\\n  font-size: 26px !important;\\n  font-weight: 900 !important;\\n  margin: 0 0 10px 0 !important;\\n  letter-spacing: -0.3px !important;\\n  line-height: 1.25 !important;\\n}\\n.hero-desc {\\n  color: #a4b0be !important;\\n  font-size: 13.5px !important;\\n  line-height: 1.6 !important;\\n  margin: 0 0 22px 0 !important;\\n  max-width: 520px !important;\\n}\\n.hero-actions {\\n  display: flex !important;\\n  align-items: center !important;\\n  gap: 18px !important;\\n  flex-wrap: wrap !important;\\n}\\n.hero-btn-play {\\n  display: inline-flex !important;\\n  align-items: center !important;\\n  gap: 8px !important;\\n  background: linear-gradient(135deg, #00d2d3, #0984e3) !important;\\n  color: #0c0d14 !important;\\n  font-size: 13px !important;\\n  font-weight: 900 !important;\\n  letter-spacing: 0.5px !important;\\n  padding: 11px 26px !important;\\n  border-radius: 25px !important;\\n  text-decoration: none !important;\\n  box-shadow: 0 6px 20px rgba(0, 210, 211, 0.45) !important;\\n  transition: all 0.25s ease !important;\\n}\\n.hero-btn-play:hover {\\n  transform: translateY(-2px) scale(1.03) !important;\\n  box-shadow: 0 10px 28px rgba(0, 210, 211, 0.65) !important;\\n  color: #000 !important;\\n}\\n.hero-live-players {\\n  color: #2ed573 !important;\\n  font-size: 12px !important;\\n  font-weight: 700 !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  gap: 6px !important;\\n}\\n.live-dot {\\n  width: 7px !important;\\n  height: 7px !important;\\n  background: #2ed573 !important;\\n  border-radius: 50% !important;\\n  display: inline-block !important;\\n  box-shadow: 0 0 8px #2ed573 !important;\\n}\\n.hero-nav-btn {\\n  position: absolute !important;\\n  top: 50% !important;\\n  transform: translateY(-50%) !important;\\n  width: 38px !important;\\n  height: 38px !important;\\n  background: rgba(12, 14, 26, 0.7) !important;\\n  backdrop-filter: blur(8px) !important;\\n  border: 1px solid rgba(255, 255, 255, 0.15) !important;\\n  color: #ffffff !important;\\n  border-radius: 50% !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  justify-content: center !important;\\n  cursor: pointer !important;\\n  z-index: 10 !important;\\n  transition: all 0.2s ease !important;\\n  padding: 0 !important;\\n}\\n.hero-nav-btn:hover {\\n  background: #00d2d3 !important;\\n  color: #0c0d14 !important;\\n  border-color: #00d2d3 !important;\\n  box-shadow: 0 0 16px rgba(0, 210, 211, 0.6) !important;\\n  transform: translateY(-50%) scale(1.1) !important;\\n}\\n.hero-prev { left: 16px !important; }\\n.hero-next { right: 16px !important; }\\n.hero-dots {\\n  position: absolute !important;\\n  bottom: 14px !important;\\n  left: 50% !important;\\n  transform: translateX(-50%) !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  gap: 7px !important;\\n  z-index: 10 !important;\\n  background: rgba(8, 10, 18, 0.65) !important;\\n  backdrop-filter: blur(6px) !important;\\n  padding: 6px 14px !important;\\n  border-radius: 20px !important;\\n  border: 1px solid rgba(255, 255, 255, 0.08) !important;\\n}\\n.hero-dot {\\n  width: 9px !important;\\n  height: 9px !important;\\n  border-radius: 50% !important;\\n  background: rgba(255, 255, 255, 0.3) !important;\\n  border: none !important;\\n  cursor: pointer !important;\\n  padding: 0 !important;\\n  transition: all 0.3s cubic-bezier(0.25, 1, 0.5, 1) !important;\\n}\\n.hero-dot.active {\\n  width: 26px !important;\\n  border-radius: 6px !important;\\n  background: #00d2d3 !important;\\n  box-shadow: 0 0 10px rgba(0, 210, 211, 0.8) !important;\\n}\\n@media (max-width: 860px) {\\n  #arcadeHeroSwiper,\\n  .arcade-hero-swiper { height: auto !important; min-height: 440px !important; }\\n  #arcadeHeroSwiper .hero-slide,\\n  .hero-slide { flex-direction: column !important; height: auto !important; }\\n  #arcadeHeroSwiper .hero-slide-img-wrap,\\n  .hero-slide-img-wrap { width: 100% !important; height: 210px !important; flex: 0 0 210px !important; }\\n  #arcadeHeroSwiper .hero-slide-overlay,\\n  .hero-slide-overlay { background: linear-gradient(to top, #101322 30%, transparent 100%) !important; }\\n  #arcadeHeroSwiper .hero-slide-content,\\n  .hero-slide-content { width: 100% !important; height: auto !important; flex: 1 1 auto !important; padding: 22px 20px 36px 20px !important; }\\n  .hero-title { font-size: 21px !important; }\\n  .hero-desc { font-size: 12.5px !important; margin-bottom: 16px !important; }\\n  .hero-nav-btn { display: none !important; }\\n}\\n</style>\\n\\n<script>\\n(function() {\\n  function startContinuousSwiper() {\\n    const swiper = document.getElementById(\\\"arcadeHeroSwiper\\\");\\n    const track = document.getElementById(\\\"heroSliderTrack\\\");\\n    const prevBtn = document.getElementById(\\\"heroNavPrev\\\");\\n    const nextBtn = document.getElementById(\\\"heroNavNext\\\");\\n    const dotsWrap = document.getElementById(\\\"heroDots\\\");\\n    const progressLine = document.getElementById(\\\"heroProgressLine\\\");\\n    if (!swiper || !track) return;\\n\\n    if (swiper.getAttribute(\\\"data-swiped\\\") === \\\"true\\\") return;\\n    swiper.setAttribute(\\\"data-swiped\\\", \\\"true\\\");\\n\\n    const slides = track.querySelectorAll(\\\".hero-slide\\\");\\n    const dots = dotsWrap ? dotsWrap.querySelectorAll(\\\".hero-dot\\\") : [];\\n    const total = slides.length;\\n    let current = 0;\\n    const intervalMs = 3200;\\n    let timer = null;\\n\\n    function resetProgress() {\\n      if (!progressLine) return;\\n      progressLine.style.transition = \\\"none\\\";\\n      progressLine.style.width = \\\"0%\\\";\\n      setTimeout(function() {\\n        progressLine.style.transition = \\\"width \\\" + (intervalMs / 1000) + \\\"s linear\\\";\\n        progressLine.style.width = \\\"100%\\\";\\n      }, 30);\\n    }\\n\\n    function update() {\\n      track.style.transform = \\\"translateX(-\\\" + (current * 100) + \\\"%)\\\";\\n      dots.forEach((d, i) => {\\n        if (i === current) {\\n          d.classList.add(\\\"active\\\");\\n        } else {\\n          d.classList.remove(\\\"active\\\");\\n        }\\n      });\\n      resetProgress();\\n    }\\n\\n    function next() {\\n      current = (current + 1) % total;\\n      update();\\n    }\\n\\n    function prev() {\\n      current = (current - 1 + total) % total;\\n      update();\\n    }\\n\\n    function restartAuto() {\\n      if (timer) clearInterval(timer);\\n      resetProgress();\\n      timer = setInterval(next, intervalMs);\\n    }\\n\\n    if (nextBtn) nextBtn.addEventListener(\\\"click\\\", function(e) { e.preventDefault(); next(); restartAuto(); });\\n    if (prevBtn) prevBtn.addEventListener(\\\"click\\\", function(e) { e.preventDefault(); prev(); restartAuto(); });\\n\\n    dots.forEach((dot, idx) => {\\n      dot.addEventListener(\\\"click\\\", function(e) {\\n        e.preventDefault();\\n        current = idx;\\n        update();\\n        restartAuto();\\n      });\\n    });\\n\\n    let startX = 0;\\n    let currentX = 0;\\n    let isDragging = false;\\n\\n    swiper.addEventListener(\\\"touchstart\\\", function(e) {\\n      startX = e.touches[0].clientX;\\n      isDragging = true;\\n    }, { passive: true });\\n\\n    swiper.addEventListener(\\\"touchmove\\\", function(e) {\\n      if (!isDragging) return;\\n      currentX = e.touches[0].clientX;\\n    }, { passive: true });\\n\\n    swiper.addEventListener(\\\"touchend\\\", function() {\\n      if (!isDragging) return;\\n      isDragging = false;\\n      const diff = currentX - startX;\\n      if (Math.abs(diff) > 40) {\\n        if (diff < 0) next();\\n        else prev();\\n        restartAuto();\\n      }\\n    });\\n\\n    update();\\n    restartAuto();\\n  }\\n\\n  if (document.readyState !== \\\"loading\\\") {\\n    startContinuousSwiper();\\n  } else {\\n    document.addEventListener(\\\"DOMContentLoaded\\\", startContinuousSwiper);\\n  }\\n  window.addEventListener(\\\"load\\\", startContinuousSwiper);\\n  setTimeout(startContinuousSwiper, 250);\\n  setTimeout(startContinuousSwiper, 1000);\\n})();\\n</script>\\n<!-- 5. FREE GAMES CATALOG -->\\n  <div id=\\\"catalog\\\" style=\\\"scroll-margin-top: 80px;\\\">\\n    <div style=\\\"display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 16px; flex-wrap: wrap; gap: 10px;\\\">\\n      <div>\\n        <span style=\\\"display: inline-block; background: rgba(0, 210, 211, 0.12); border: 1px solid #00d2d3; color: #00d2d3; font-size: 11px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase; padding: 4px 12px; border-radius: 20px; margin-bottom: 8px;\\\">🎮 ARCADE VAULT</span>\\n        <h3 style=\\\"font-size: 26px; margin: 0; color: #fff; font-weight: 900; letter-spacing: 0.5px;\\\">🔥 Games</h3>\\n      </div>\\n      <span style=\\\"color: #2ed573; font-size: 13px; font-weight: bold;\\\">● 24,800+ Online Now</span>\\n    </div>\\n\\n    <!-- CATEGORY FILTER PILLS -->\\n    <div class=\\\"cat-filter-wrap\\\" style=\\\"displa