align-items: stretch !important;\\n}\\n@media (max-width: 960px) {\\n  .esports-shop-duo {\\n    grid-template-columns: 1fr !important;\\n  }\\n}\\n\\n.duo-panel {\\n  background: linear-gradient(135deg, #101322 0%, #151829 100%) !important;\\n  border: 1px solid #282f4d !important;\\n  border-radius: 20px !important;\\n  padding: 24px 22px !important;\\n  display: flex !important;\\n  flex-direction: column !important;\\n  box-shadow: 0 14px 40px rgba(0,0,0,0.5) !important;\\n  box-sizing: border-box !important;\\n}\\n.shop-panel {\\n  background: linear-gradient(135deg, #121026 0%, #1a1636 100%) !important;\\n  border-color: #3b2c63 !important;\\n}\\n\\n.panel-header {\\n  display: flex !important;\\n  justify-content: space-between !important;\\n  align-items: flex-start !important;\\n  margin-bottom: 18px !important;\\n  flex-wrap: wrap !important;\\n  gap: 10px !important;\\n}\\n.panel-badge {\\n  font-size: 10.5px !important;\\n  font-weight: 800 !important;\\n  letter-spacing: 1.5px !important;\\n  text-transform: uppercase !important;\\n  color: #00d2d3 !important;\\n  display: block !important;\\n  margin-bottom: 4px !important;\\n}\\n.panel-title {\\n  font-size: 22px !important;\\n  font-weight: 900 !important;\\n  margin: 0 !important;\\n  color: #ffffff !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  gap: 8px !important;\\n}\\n.panel-pill {\\n  font-size: 11px !important;\\n  font-weight: 800 !important;\\n  padding: 5px 12px !important;\\n  border-radius: 20px !important;\\n  white-space: nowrap !important;\\n}\\n\\n/* LEADERBOARD LIST */\\n.podium-box {\\n  display: grid !important;\\n  grid-template-columns: 1fr !important;\\n  gap: 10px !important;\\n  margin-bottom: 16px !important;\\n}\\n.rank-item {\\n  background: rgba(16, 19, 34, 0.7) !important;\\n  border: 1px solid #22263d !important;\\n  border-radius: 14px !important;\\n  padding: 11px 15px !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  justify-content: space-between !important;\\n  transition: transform 0.2s, border-color 0.2s !important;\\n}\\n.rank-item:hover {\\n  transform: translateY(-2px) !important;\\n}\\n.rank-item.rank-1-item {\\n  background: linear-gradient(135deg, rgba(254, 202, 87, 0.12) 0%, rgba(20, 22, 38, 0.8) 100%) !important;\\n  border: 1px solid rgba(254, 202, 87, 0.5) !important;\\n  box-shadow: 0 4px 20px rgba(254, 202, 87, 0.15) !important;\\n}\\n.rank-item.rank-2-item {\\n  border-color: rgba(200, 214, 229, 0.4) !important;\\n}\\n.rank-item.rank-3-item {\\n  border-color: rgba(255, 159, 67, 0.4) !important;\\n}\\n.rank-left {\\n  display: flex !important;\\n  align-items: center !important;\\n  gap: 12px !important;\\n}\\n.rank-badge {\\n  width: 32px !important;\\n  height: 32px !important;\\n  border-radius: 10px !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  justify-content: center !important;\\n  font-size: 15px !important;\\n  font-weight: 900 !important;\\n  flex-shrink: 0 !important;\\n}\\n.badge-1 { background: linear-gradient(135deg, #feca57, #ff9f43) !important; color: #000 !important; box-shadow: 0 0 12px rgba(254, 202, 87, 0.6) !important; }\\n.badge-2 { background: linear-gradient(135deg, #c8d6e5, #8395a7) !important; color: #000 !important; }\\n.badge-3 { background: linear-gradient(135deg, #ff9f43, #ee5253) !important; color: #fff !important; }\\n.badge-runner { background: rgba(255,255,255,0.06) !important; color: #a4b0be !important; font-size: 13px !important; font-weight: 800 !important; }\\n\\n.player-info-title {\\n  font-size: 13.5px !important;\\n  font-weight: 800 !important;\\n  color: #fff !important;\\n  display: flex !important;\\n  align-items: center !important;\\n  gap: 6px !important;\\n}\\n.player-meta {\\n  font-size: 11px !important;\\n  color: #747d8c !important;\\n  margin-top: 2px !important;\\n}\\n.player-meta b {\\n  color: #00d2d3 !important;\\n  font-weight: 700 !important;\\n}\\n.rank-right {\\n  text-align: right !important;\\n}\\n.rank-elo {\\n  font-size: 14.5px !important;\\n  font-weight: 900 !important;\\n  color: #feca57 !important;\\n}\\n.rank-winrate {\\n  font-size: 11px !important;\\n  color: #2ed573 !important;\\n  font-weight: 700 !important;\\n}\\n\\n/* SHOP PRODUCTS GRID */\\n.shop-filter-bar {\\n  display: flex !important;\\n  gap: 8px !important;\\n  overflow-x: auto !important;\\n  padding-bottom: 8px !important;\\n  margin-bottom: 14px !important;\\n}\\n.shop-chip {\\n  font-size: 11.5px !important;\\n  font-weight: 800 !important;\\n  padding: 6px 16px !important;\\n  border-radius: 14px !important;\\n  background: rgba(255, 255, 255, 0.05) !important;\\n  border: 1px solid rgba(255, 255, 255, 0.12) !important;\\n  color: #a4b0be !important;\\n  white-space: nowrap !important;\\n  cursor: pointer !important;\\n  text-decoration: none !important;\\n  transition: all 0.2s ease !important;\\n  user-select: none !important;\\n}\\n.shop-chip.active, .shop-chip:hover {\\n  background: #ff9ff3 !important;\\n  color: #0c0d14 !important;\\n  border-color: #ff9ff3 !important;\\n  box-shadow: 0 0 14px rgba(255, 159, 243, 0.4) !important;\\n}\\n\\n.shop-grid {\\n  display: grid !important;\\n  grid-template-columns: repeat(2, 1fr) !important;\\n  gap: 11px !important;\\n  margin-bottom: 14px !important;\\n  align-content: start !important;\\n}\\n@media (max-width: 580px) {\\n  .shop-grid { grid-template-columns: 1fr !important; }\\n}\\n\\n.shop-card {\\n  background: #101221 !important;\\n  border: 1px solid #282447 !important;\\n  border-radius: 14px !important;\\n  overflow: hidden !important;\\n  display: flex !important;\\n  flex-direction: column !important;\\n  transition: transform 0.2s, border-color 0.2s, box-shadow 0.2s !important;\\n  position: relative !important;\\n}\\n.shop-card.shop-hidden {\\n  display: none !important;\\n}\\n.shop-card:hover {\\n  transform: translateY(-3px) !important;\\n  border-color: #ff9ff3 !important;\\n  box-shadow: 0 8px 24px rgba(255, 159, 243, 0.25) !important;\\n}\\n.shop-thumb-wrap {\\n  width: 100% !important;\\n  height: 110px !important;\\n  position: relative !important;\\n  overflow: hidden !important;\\n  background: #090a14 !important;\\n}\\n.shop-thumb-wrap img {\\n  position: absolute !important;\\n  top: 0 !important; left: 0 !important;\\n  width: 100% !important;\\n  height: 100% !important;\\n  object-fit: cover !important;\\n  transition: transform 0.4s ease !important;\\n}\\n.shop-card:hover .shop-thumb-wrap img {\\n  transform: scale(1.08) !important;\\n}\\n.shop-tag {\\n  position: absolute !important;\\n  top: 6px !important; left: 6px !important;\\n  background: rgba(8, 10, 18, 0.85) !important;\\n  backdrop-filter: blur(4px) !important;\\n  border: 1px solid rgba(255, 159, 243, 0.4) !important;\\n  color: #ff9ff3 !important;\\n  font-size: 8.5px !important;\\n  font-weight: 800 !important;\\n  padding: 2px 6px !important;\\n  border-radius: 4px !important;\\n  text-transform: uppercase !important;\\n  letter-spacing: 0.5px !important;\\n  z-index: 2 !important;\\n}\\n.shop-discount {\\n  position: absolute !important;\\n  top: 6px !important; right: 6px !important;\\n  background: #ff4757 !important;\\n  color: #fff !important;\\n  font-size: 9px !important;\\n  font-weight: 900 !important;\\n  padding: 2px 5px !important;\\n  border-radius: 4px !important;\\n  z-index: 2 !important;\\n}\\n.shop-body {\\n  padding: 9px 11px !important;\\n  display: flex !important;\\n  flex-direction: column !important;\\n  gap: 5px !important;\\n  flex: 1 !important;\\n  justify-content: space-between !important;\\n}\\n.shop-item-title {\\n  font-size: 12px !important;\\n  font-weight: 800 !important;\\n  color: #ffffff !important;\\n  margin: 0 !important;\\n  white-space: nowrap !important;\\n  overflow: hidden !important;\\n  text-overflow: ellipsis !important;\\n}\\n.shop-price-row {\\n  display: flex !important;\\n  align-items: baseline !important;\\n  gap: 8px !important;\\n  margin: 2px 0 !important;\\n}\\n.shop-old-price {\\n  font-size: 11px !important;\\n  color: #747d8c !important;\\n  text-decoration: line-through !important;\\n}\\n.shop-new-price {\\n  font-size: 14.5px !important;\\n  font-weight: 900 !important;\\n  color: #2ed573 !important;\\n}\\n.shop-buy-btn {\\n  display: block !important;\\n  width: 100% !important;\\n  text-align: center !important;\\n  background: linear-gradient(135deg, #ff4757, #ff6b81) !important;\\n  color: #fff !important;\\n  font-size: 10.5px !important;\\n  font-weight: 800 !important;\\n  padding: 6px 0 !important;\\n  border-radius: 7px !important;\\n  text-decoration: none !important;\\n  letter-spacing: 0.5px !important;\\n  transition: 0.2s !important;\\n  box-shadow: 0 3px 12px rgba(255, 71, 87, 0.3) !important;\\n}\\n.shop-buy-btn:hover {\\n  background: #ff6b81 !important;\\n  box-shadow: 0 4px 16px rgba(255, 71, 87, 0.5) !important;\\n  color: #fff !important;\\n}\\n\\n.panel-footer-perks {\\n  border-top: 1px solid rgba(255,255,255,0.08) !important;\\n  padding-top: 10px !important;\\n  margin-top: auto !important;\\n  display: flex !important;\\n  justify-content: space-between !important;\\n  font-size: 10.5px !important;\\n  color: #a4b0be !important;\\n  flex-wrap: wrap !important;\\n  gap: 6px !important;\\n}\\n</style>\\n\\n  <div class=\\\"discord-box\\\">\\r\\n    <h3 style=\\\"margin: 0 0 10px 0; font-size: 24px; color: #fff;\\\">👾 JOIN 50,000+ GAMERS ON DISCORD</h3>\\r\\n    <p style=\\\"color: #d1d8e0; font-size: 14px; margin: 0 0 20px 0;\\\">Participate in weekly high-score tournaments, unlock custom gamer badges, and chat directly with game developers.</p>\\r\\n    <a href=\\\"#\\\" class=\\\"btn-primary\\\" style=\\\"background: #fff; color: #4752c4; font-weight: 900;\\\">JOIN DISCORD SERVER &raquo;</a>\\r\\n  </div>\\r\\n\\r\\n  <!-- ========================================================\\r\\n       9. CONTACT US & ABOUT US HUB (NEW!)