\n  }\\r\\n  .btn-primary {\\r\\n    background: linear-gradient(135deg, #00d2d3, #54a0ff);\\r\\n    color: #0c0d14;\\r\\n    font-weight: 800;\\r\\n    font-size: 14px;\\r\\n    padding: 12px 28px;\\r\\n    border-radius: 30px;\\r\\n    text-decoration: none;\\r\\n    box-shadow: 0 8px 25px rgba(0, 210, 211, 0.4);\\r\\n    transition: 0.3s;\\r\\n  }\\r\\n  .btn-primary:hover {\\r\\n    transform: translateY(-3px);\\r\\n    box-shadow: 0 12px 30px rgba(0, 210, 211, 0.6);\\r\\n    color: #000;\\r\\n  }\\r\\n  .btn-secondary {\\r\\n    background: rgba(255, 255, 255, 0.05);\\r\\n    border: 1px solid #3d3b66;\\r\\n    color: #fff;\\r\\n    font-weight: 700;\\r\\n    font-size: 14px;\\r\\n    padding: 12px 28px;\\r\\n    border-radius: 30px;\\r\\n    text-decoration: none;\\r\\n    transition: 0.3s;\\r\\n  }\\r\\n\\r\\n  \\/* STATS BAR *\\/\\r\\n  .stats-bar {\\r\\n    display: flex;\\r\\n    justify-content: center;\\r\\n    gap: 40px;\\r\\n    border-top: 1px solid #1f2136;\\r\\n    padding-top: 25px;\\r\\n    flex-wrap: wrap;\\r\\n  }\\r\\n  .stat-item { text-align: center; }\\r\\n  .stat-num { font-size: 24px; font-weight: 900; color: #feca57; }\\r\\n  .stat-label { font-size: 12px; color: #747d8c; text-transform: uppercase; letter-spacing: 1px; }\\r\\n\\r\\n  \\/* 2. SPONSOR AD BAR (728x90) *\\/\\r\\n  .ad-slot-wrap {\\r\\n    margin: 0 auto 35px auto;\\r\\n    max-width: 728px;\\r\\n    background: #11131c;\\r\\n    border: 1px dashed #feca57;\\r\\n    border-radius: 10px;\\r\\n    padding: 12px 20px;\\r\\n    display: flex;\\r\\n    justify-content: space-between;\\r\\n    align-items: center;\\r\\n    flex-wrap: wrap;\\r\\n    gap: 10px;\\r\\n  }\\r\\n\\r\\n  \\/* 3. CATEGORY TABS *\\/\\r\\n  .cat-tabs {\\r\\n    display: flex;\\r\\n    gap: 10px;\\r\\n    overflow-x: auto;\\r\\n    padding-bottom: 10px;\\r\\n    margin-bottom: 25px;\\r\\n  }\\r\\n  .tab-pill {\\r\\n    background: #151824;\\r\\n    border: 1px solid #24293d;\\r\\n    color: #a4b0be;\\r\\n    f