(20,1,'2026-11-13 09:58:45','2026-11-13 09:58:45','{\n    \"custom_css[vr-gaming]\": {\n        \"value\": \".feature-header {\\n  display: none !important;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-11-13 09:58:45\"\n    }\n}','','','trash','closed','closed','','e727adcc-8f04-416d-8464-08559a200fc0','','','2026-11-13 09:58:45','2026-11-13 09:58:45','',0,'http://localhost/wordpress/?p=20',0,'customize_changeset','',0),
(21,1,'2026-11-13 09:58:45','2026-11-13 09:58:45','/* 1. HIDE THAT UGLY CASINO ARCHIVE BANNER */\n.feature-header {\n  display: none !important;\n}\n\n/* 2. SLEEK DARK ARCADE BACKGROUND */\nbody, #content, .site-content {\n  background-color: #0b0c10 !important;\n  color: #c5c6c7 !important;\n}\n\n/* 3. GLOWING MODERN GAME CARDS */\n.card, article.post, .widget, .sidebar {\n  background-color: #151821 !important;\n  border-radius: 12px !important;\n  border: 1px solid #1f2430 !important;\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5) !important;\n  color: #e0e0e0 !important;\n}\n\n/* 4. NEON TITLES & LINKS */\nh1, h2, h3, .entry-title a, .post-title a {\n  color: #00d2d3 !important;\n}\n\n.entry-title a:hover {\n  color: #ff9ff3 !important;\n}\n\n/* 5. TOP HEADER BAR */\nheader, .site-header, .navbar {\n  background-color: #07080c !important;\n  border-bottom: 2px solid #00d2d3 !important;\n	\n	/* Saari Wording (Text) ko White karne ke liye */\nbody, p, span, div, li {\n  color: #ffffff !important;\n}\n\n/* Titles aur Headings ko Bright White/Cyan karne ke liye */\nh1, h2, h3, h4, h5, h6, .post-title, .entry-title {\n  color: #ffffff !important;\n}\n\n/* Game Links aur Click hone wale text ko Bright Neon karne ke liye */\na {\n  color: #00d2d3 !important;\n}\n\na:hover {\n  color: #feca57 !important;\n}\n	\n	/* 1. BEKAAR CALENDAR, ARCHIVES, PAGES KO PURA GAYAB KARO */\n#footer-widgets {\n  display: none !important;\n}\n\n/* 2. SLEEK PRO GAMING FOOTER */\nfooter {\n  background-color: #07080c !important;\n  border-top: 1px solid #1b202e !important;\n  margin-top: 50px !important;\n}\n\n.copyright {\n  background: transparent !important;\n  text-align: center !important;\n  padding: 25px 0 !important;\n}\n\n.copy-text p, .copy-text a {\n  color: #747d8c !important;\n  font-size: 14px !important;\n  text-decoration: none !important;\n}\n\n.copy-text a:hover {\n  color: #00d2d3 !important;\n}\n	\n	','vr-gaming','','publish','closed','closed','','vr-gaming','','','2026-11-13 10:45:56','2026-11-13 10:45:56','',0,'http://localhost/wordpress/?p=21',0,'custom_css','',0),
